#include <iostream>

void solveEquation(double a, double b, double c, double d,
                   double e, double f, double& x, double& y, bool& isSolvable) {
    double det = a * d - b * c;
    if (det == 0.0) {
        isSolvable = false;
        x = 0.0;
        y = 0.0;
    } else {
        isSolvable = true;
        x = (e * d - b * f) / det;
        y = (a * f - e * c) / det;
    }
}

int main() {
    double a = 9.0, b = 4.0, c = 3.0, d = -5.0, e = -6.0, f = -21.0;
    double x = 0.0, y = 0.0;
    bool solvable = false;

    solveEquation(a, b, c, d, e, f, x, y, solvable);

    if (solvable) {
        std::cout << "x = " << x << ", y = " << y << "\n";
    } else {
        std::cout << "The equation has no solution.\n";
    }
    return 0;
}

#include <iostream>
#include <string>

int getDigit(int number) {
    if (number < 10) return number;
    return (number / 10) + (number % 10);
}

int sumOfDoubleEvenPlace(const std::string& cardNumber) {
    int sum = 0;
    // Duyet tu phai sang trai, bat dau tu vi tri chan thu 2 tu cuoi
    for (int i = static_cast<int>(cardNumber.length()) - 2; i >= 0; i -= 2) {
        sum += getDigit((cardNumber[i] - '0') * 2);
    }
    return sum;
}

int sumOfOddPlace(const std::string& cardNumber) {
    int sum = 0;
    // Duyet tu phai sang trai, cac vi tri le tu cuoi
    for (int i = static_cast<int>(cardNumber.length()) - 1; i >= 0; i -= 2) {
        sum += (cardNumber[i] - '0');
    }
    return sum;
}

bool isValid(const std::string& cardNumber) {
    int total = sumOfDoubleEvenPlace(cardNumber) + sumOfOddPlace(cardNumber);
    return (total % 10 == 0);
}

int main() {
    std::string card1 = "4388576018402626";
    std::string card2 = "4388576018410707";

    std::cout << card1 << " is " << (isValid(card1) ? "valid" : "invalid") << "\n";
    std::cout << card2 << " is " << (isValid(card2) ? "valid" : "invalid") << "\n";
    return 0;
}

