// Chuyen thap phan sang bat phan (dang so nguyen)
int dec2Octal(const int& decimal) {
    int dec = decimal;
    int octal = 0;
    int place = 1;
    while (dec > 0) {
        octal += (dec % 8) * place;
        dec /= 8;
        place *= 10;
    }
    return octal;
}

// Chuyen bat phan sang thap phan
int octal2Dec(const int& octalNumber) {
    int oct = octalNumber;
    int decimal = 0;
    int powerOfEight = 1;
    while (oct > 0) {
        int digit = oct % 10;
        decimal += digit * powerOfEight;
        powerOfEight *= 8;
        oct /= 10;
    }
    return decimal;
}

int main() {
    int dec = 229;
    int oct = dec2Octal(dec);
    std::cout << dec << " in octal is " << oct << "\n";
    std::cout << oct << " back to decimal is " << octal2Dec(oct) << "\n";
    return 0;
}
